/*
 * ngtcp2 version header — normally generated by ngtcp2's CMake/autotools from
 * lib/includes/ngtcp2/version.h.in. Hand-written here so the AmebaD build does
 * not need ngtcp2's configure step. Keep in sync with the pinned submodule tag
 * (component/thirdparty/ngtcp2 @ v1.23.0).
 */
#ifndef NGTCP2_VERSION_H
#define NGTCP2_VERSION_H

/* Version number of the ngtcp2 library release. */
#define NGTCP2_VERSION "1.23.0"

/* Numerical representation: 8 bits major | 8 bits minor | 8 bits patch.
 * 1.23.0 -> 0x01 0x17 0x00. */
#define NGTCP2_VERSION_NUM 0x011700

#endif /* !defined(NGTCP2_VERSION_H) */
